const cleanObject = (obj: Fields): Fields => {
    const out: Fields = {};
    for (const [key, value] of Object.entries(obj)) {
        if (value === undefined) continue;
        out[key] = redact.has(key.toLowerCase()) ? "[REDACTED]" : clean(value);
    }
    return out;
};

